type View = "overview" | "scans" | "results" | "findings" | "reports" | "lab" | "team" | "admin" | "profile";
type ScanMode = "fast" | "deep" | "complete";
type ScanStatus = "queued" | "running" | "completed" | "failed";
type Severity = "critical" | "high" | "medium" | "low";
type FindingStatus = "open" | "triaged" | "resolved";
type Notify = (message: string) => void;

type Finding = {
  id: string; title: string; category: string; severity: Severity; confidence: number; endpoint: string;
  evidence: string; recommendation: string; status: FindingStatus; score: string; detected: string; asvs: string;
};

type LiveScanJob = {
  id: string; projectId: string; assetId: string; target: string; scanMode: string; status: ScanStatus;
  progress: number; currentStep: string; reportHash?: string; finalUrl?: string; httpStatus?: number; coverage?: string; checksRun?: number;
  checkedAt?: string; createdAt?: string;
  findings?: Array<{ id: string; title: string; category: string; severity: "low" | "medium" | "high"; confidence: number; endpoint: string; evidence?: Record<string, string>; recommendation: string; status: "open" }>;
};

